	for _, c := range cases {
		got := Unique(c.in)
		if len(got) == 0 && len(c.want) == 0 {
			continue
		}
		if !reflect.DeepEqual(got, c.want) {
			t.Errorf("Unique(%v) = %v, want %v", c.in, got, c.want)
		}
	}
}

