// negative to subtract.
func AddBusinessDays(t time.Time, n int) time.Time {
	if n == 0 {
		return t
	}

	result := t
	step := time.Hour * 24 // One day

	if n > 0 {
		for n > 0 {
			result = result.Add(step)
			if !IsWeekend(result) {
				n--
			}
		}
	} else {
		for n < 0 {
			result = result.Add(-step)
			if !IsWeekend(result) {
				n++
			}
		}
	}

	return result
}"}

