		t.Errorf("Friday + 1 BD = %v, want Monday", next.Weekday())
	}

	// Test adding multiple business days across weekends
	mon := time.Date(2026, 1, 5, 12, 0, 0, 0, time.UTC) // Monday
	next = AddBusinessDays(mon, 5)
