	if !next.Equal(expectedDate) {
		t.Errorf("Monday + 5 BD = %v, want %v", next, expectedDate)
	}

	// Test subtracting business days across weekends
	tue := time.Date(2026, 1, 6, 12, 0, 0, 0, time.UTC) // Tuesday
	prev := AddBusinessDays(tue, -1)
	if prev.Weekday() != time.Monday {
		t.Errorf("Tuesday - 1 BD = %v, want Monday", prev.Weekday())
	}

	// Test zero days
	wed := time.Date(2026, 1, 7, 12, 0, 0, 0, time.UTC) // Wednesday
	same := AddBusinessDays(wed, 0)
