	}
	expectedDate = time.Date(2026, 1, 2, 12, 0, 0, 0, time.UTC)
	if !prev.Equal(expectedDate) {
		t.Errorf("Friday - 5 BD = %v, want %v", prev, expectedDate)
	}
}"}

