package taskpkg

// Gcd calculates the greatest common divisor of two integers using the Euclidean algorithm.
// It handles negative inputs by converting them to absolute values.
func Gcd(a, b int) int {
	if a < 0 {
		a = -a
	}
	if b < 0 {
		b = -b
	}
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

package taskpkg

import "testing"

func TestGcd(t *testing.T) {
	// Test case 1: Basic positive numbers
	result := Gcd(48, 18)
	expected := 6
	if result != expected {
		t.Errorf("Gcd(48, 18) = %d; expected %d", result, expected)
	}

	// Test case 2: One negative number
	result = Gcd(-48, 18)
	expected = 6
	if result != expected {
		t.Errorf("Gcd(-48, 18) = %d; expected %d", result, expected)
	}

	// Test case 3: Both negative numbers
	result = Gcd(-48, -18)
	expected = 6
	if result != expected {
		t.Errorf("Gcd(-48, -18) = %d; expected %d", result, expected)
	}

	// Test case 4: One number is zero
	result = Gcd(0, 18)
	expected = 18
	if result != expected {
		t.Errorf("Gcd(0, 18) = %d; expected %d", result, expected)
	}
}

